@Configuration
@EnableStateMachineFactory
class OrderFlow extends StateMachineConfigurerAdapter<OrderState, OrderEvent> {
  @Override
  public void configure(StateMachineTransitionConfigurer<OrderState, OrderEvent> t) throws Exception {
    t.withExternal().source(AWAITING_PAYMENT).target(AWAITING_STOCK)
     .event(PAYMENT_OK).action(reserveStock())
     .and().withExternal().source(AWAITING_PAYMENT).target(COMPENSATING)
     .event(PAYMENT_TIMEOUT).action(releaseCredit());
  }
}
