@WorkflowInterface
public interface OrderWorkflow {
  @WorkflowMethod
  void run(Order order);
}

public class OrderWorkflowImpl implements OrderWorkflow {
  private final Activities activities = Workflow.newActivityStub(Activities.class, opts);
  public void run(Order order) {
    activities.reserveCredit(order);
    boolean paid = Workflow.await(Duration.ofHours(1), () -> paymentOk);
    if (!paid) {
      activities.releaseCredit(order);                 // compensation
      throw ApplicationFailure.newNonRetryableFailure("payment timeout", "timeout");
    }
    activities.ship(order);
  }
}
